function fmtHL(lh){if(lh==null)return 'stable';const t=10**lh;const u=[[1e-21,'zs'],[1e-18,'as'],[1e-15,'fs'],[1e-12,'ps'],[1e-9,'ns'],[1e-6,'µs'],[1e-3,'ms'],[1,'seconds'],[60,'minutes'],[3600,'hours'],[86400,'days'],[yr,'years'],[1e3*yr,'thousand years'],[1e6*yr,'million years'],[1e9*yr,'billion years'],[1e12*yr,'trillion years']];let b=u[0];for(const x of u)if(t>=x[0])b=x;let v=t/b[0];if(b[1]==='trillion years'&&v>=1000)return sci(t/yr,'years');return (v<10?v.toPrecision(3):v<1000?Math.round(v):Math.round(v).toLocaleString())+' '+b[1];}
