function buildNucleus(){clear(Lg.nucleus);if(!selIso)return;const Z=selIso.z,A=selIso.a,d=0.16,pts=[];const R=Math.ceil(Math.cbrt(A))+2;
 for(let i=-R;i<=R;i++)for(let j=-R;j<=R;j++)for(let k=-R;k<=R;k++){const o=((i+j+k)%2+2)%2;if(o)continue;pts.push([i,j,k]);}
 pts.sort((a,b)=>(a[0]**2+a[1]**2+a[2]**2)-(b[0]**2+b[1]**2+b[2]**2)||a[0]-b[0]||a[1]-b[1]);const use=pts.slice(0,A);
 let seed=Z*7919+A;const rnd=()=>{seed=(seed*16807)%2147483647;return seed/2147483647;};const idx=use.map((_,i)=>i);for(let i=idx.length-1;i>0;i--){const j=Math.floor(rnd()*(i+1));[idx[i],idx[j]]=[idx[j],idx[i]];}
 const isP=new Set(idx.slice(0,Z)),g=new THREE.SphereGeometry(d*0.78,14,10),mP=new THREE.MeshPhongMaterial({color:0xde5f37,shininess:40}),mN=new THREE.MeshPhongMaterial({color:0x9aa3ab,shininess:40});
 const ip=new THREE.InstancedMesh(g,mP,Z),inn=new THREE.InstancedMesh(g.clone(),mN,Math.max(1,A-Z));const M=new THREE.Matrix4();let a=0,b=0;
 use.forEach((p,i)=>{M.makeTranslation(p[0]*d*0.72,p[1]*d*0.72,p[2]*d*0.72);if(isP.has(i))ip.setMatrixAt(a++,M);else inn.setMatrixAt(b++,M);});
 inn.count=A-Z;Lg.nucleus.add(ip);if(A>Z)Lg.nucleus.add(inn);else disposeObj(inn);}
